// OpenFreeMap + pinned MapLibre. No API keys, billing accounts or Google SDK.
export const MAP_STYLE='https://tiles.openfreemap.org/styles/liberty';
export function parseCoordinates(value){const match=String(value).trim().match(/^(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)$/);if(!match)return null;const lat=Number(match[1]),lng=Number(match[2]);return Math.abs(lat)<=90&&Math.abs(lng)<=180?{lat,lng}:null;}
let map,library,markers=[],lastPoints=[],selectTarget=null;
function loadLibrary(){if(window.maplibregl)return Promise.resolve(window.maplibregl);if(library)return library;library=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://unpkg.com/maplibre-gl@5.12.0/dist/maplibre-gl.js';const timeout=setTimeout(()=>reject(Error('Map library timed out. Check your connection and retry.')),20000);script.onload=()=>{clearTimeout(timeout);window.maplibregl?resolve(window.maplibregl):reject(Error('Map library unavailable.'));};script.onerror=()=>{clearTimeout(timeout);reject(Error('Map library could not load.'));};document.head.append(script);}).catch(e=>{library=null;throw e;});return library;}
export async function startMap({onPick,onStatus}){if(map){map.resize();onStatus('Reloading free map…');map.setStyle(MAP_STYLE);map.once('idle',()=>onStatus('OpenFreeMap · no API key or billing'));return;}onStatus('Loading free map…');try{const lib=await loadLibrary();map=new lib.Map({container:'freeMap',style:MAP_STYLE,center:[28.5,39.9],zoom:6.1,attributionControl:true});map.addControl(new lib.NavigationControl({showCompass:false}),'top-right');map.addControl(new lib.ScaleControl({unit:'metric'}),'bottom-left');const timeout=setTimeout(()=>onStatus('Map loading is taking longer than expected. Navigation links still work.'),20000);map.on('style.load',()=>showRoad(routeGeometry));map.on('load',()=>{clearTimeout(timeout);onStatus('OpenFreeMap · no API key or billing');updatePins(lastPoints);});map.on('error',()=>onStatus('Some map data could not load. Check your connection; navigation links still work.'));map.on('click',e=>{if(!selectTarget)return;const target=selectTarget;selectTarget=null;map.getCanvas().style.cursor='';onPick(target,{lat:e.lngLat.lat,lng:e.lngLat.lng});});}catch(e){onStatus(e.message);throw e;}}
export function selectOnMap(target){selectTarget=target;if(map)map.getCanvas().style.cursor='crosshair';}
export function updatePins(points,{focus=false}={}){lastPoints=points;if(!map||!window.maplibregl)return;markers.forEach(m=>m.remove());markers=[];for(const p of points){const node=document.createElement('div');node.className='ev-map-pin';node.textContent=p.label;node.setAttribute('aria-label',p.title);const popup=new window.maplibregl.Popup({offset:25}).setText(p.title);markers.push(new window.maplibregl.Marker({element:node}).setLngLat([p.lng,p.lat]).setPopup(popup).addTo(map));}if(focus&&points.length){if(points.length===1)map.flyTo({center:[points[0].lng,points[0].lat],zoom:13});else{const bounds=new window.maplibregl.LngLatBounds();points.forEach(p=>bounds.extend([p.lng,p.lat]));map.fitBounds(bounds,{padding:65,maxZoom:14});}}}
export function fitPins(){updatePins(lastPoints,{focus:true});}

let routeGeometry=null;
export function showRoad(geometry,{focus=false}={}){routeGeometry=geometry;if(!map||!map.isStyleLoaded())return;const data={type:'Feature',properties:{},geometry:geometry||{type:'LineString',coordinates:[]}};if(map.getSource('trip-road'))map.getSource('trip-road').setData(data);else{map.addSource('trip-road',{type:'geojson',data});map.addLayer({id:'trip-road',type:'line',source:'trip-road',paint:{'line-color':'#287cbb','line-width':5,'line-opacity':.85},layout:{'line-join':'round','line-cap':'round'}});}if(focus&&geometry?.coordinates?.length){const bounds=new window.maplibregl.LngLatBounds();geometry.coordinates.forEach(p=>bounds.extend(p));map.fitBounds(bounds,{padding:55,maxZoom:14});}}
